                                            }`}
                                    >
                                        <config.icon size={11} />
                                        {t(config.labelKey)}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {filteredSkills.map((skill, idx) => {
                                const config = CATEGORY_CONFIG[skill.category];
