                    }`}>
                    <Activity size={12} className={patient.deteriorationRate > 0 ? 'animate-pulse' : ''} />
                    {patient.deteriorationRate <= 0
                        ? t('emergency.ui.deteriorationPlateau')
                        : t('emergency.ui.deteriorationWorsening', { value: patient.deterioration })}
                </div>
            )}
        </button>
    );
}

