    );
    const getBillingItemLabel = useCallback(
        (detail) => {
            if (detail?.actionId) return getActionLabel(detail.actionId);
            if (detail?.medId && EMERGENCY_ACTIONS[detail.medId]) return getActionLabel(detail.medId);
            return detail?.name || '-';
        },
