                </StepCarousel>
            </div>
        </div>
    );
}

function SectionTitle({ children, isDark }) {
    return (
        <h3 className={`text-sm font-black uppercase tracking-widest ${isDark ? 'text-slate-300' : 'text-slate-700'}`}>
            {children}
        </h3>
