function generateAegisProfile(energy, reputation) {
    for (const profile of AEGIS_CODENAMES) {
        if (energy >= profile.minEnergy && reputation <= profile.maxRep) return profile;
    }

    return AEGIS_CODENAMES[AEGIS_CODENAMES.length - 1];
}

