                        <ShieldCheck size={36} className="text-emerald-400" />
                    </div>
                    <h1 className="font-display mb-2 text-4xl font-black leading-tight tracking-widest text-white drop-shadow-[0_0_20px_rgba(16,185,129,0.5)] md:text-5xl">
                        AEGIS
