                        REGISTRY
                    </h1>
                    <p className="mb-10 inline-block border border-emerald-900 bg-emerald-950/50 px-2 py-1 text-[10px] font-bold uppercase tracking-[0.3em] text-emerald-400">
                        {t('playerSetup.panel.protocol')}
