        setPlayerStats(prev => ({
            ...prev,
            energy: Math.max(0, (Number(prev?.energy) || 0) - effectiveEnergy)
        }));
        addXp(action.xp);

        if (updateProgress) {
            getHomeVisitProgressMetrics(action.id).forEach(metric => {
                updateProgress(metric, 1);
            });
        }

