                                className={`${isCompactHud ? 'px-2 py-1.5 text-[9px]' : isCompressedHud ? 'px-2.5 py-1.5 text-[9px]' : 'px-3 py-1.5 text-[10px]'} rounded-lg font-black uppercase tracking-wider ${GLASS} ${GLASS_HOVER} text-amber-300`}
