                                if (result?.totalXP) addXp(result.totalXP);

                                // 2. Reputation + Energy cost (30 EP per session)
                                setPlayerStats(prev => ({
                                    ...prev,
                                    reputation: Math.min(100, Math.max(0, (prev.reputation || 50) + (result?.repDelta || 0))),
