        label: 'Sawah / Pos UKK',
        priorities: [BUILDING_TYPES.FARM, BUILDING_TYPES.POS_UKK, BUILDING_TYPES.SAWAH_BERUNDAK, BUILDING_TYPES.PUSTU]
