        label: 'Komunitas',
        priorities: [BUILDING_TYPES.BALAI_DESA, BUILDING_TYPES.MARKET, BUILDING_TYPES.SCHOOL, BUILDING_TYPES.PUSTU]
    },
    {
        match: ({ category }) => category === 'phbs',
