    // KMS card
    drawRect(ctx, s(178), s(96), s(16), s(10), '#a0d080');
    drawRect(ctx, s(180), s(97), s(12), s(1), PAL.wood_dark);
    drawRect(ctx, s(180), s(99), s(12), s(1), PAL.wood_dark);
