// ═══════════════════════════════════════════════════════════════
// CORE DEBRIEF GENERATOR
// ═══════════════════════════════════════════════════════════════

/**
 * Generate end-of-day debrief from today's case log.
 * 
 * @param {Object} params
 * @param {Array} params.todayLog - Array of case outcome records
 * @param {Array} params.consequenceQueue - Current consequence queue
 * @param {number} params.day - Current game day
 * @param {Object} params.stats - Financial/reputation stats
 * @param {string|null} params.dailyQuestId - Selected daily quest ID
 * @param {Object|null} params.morningReputation - Reputation at start of day (for delta)
 * @param {Object|null} params.bcState - UKM Behavior Change state for BC progress summary
 * @param {Array} params.bcState.activeCases - Currently active BC cases
 * @param {Array} params.bcState.completedToday - BC cases completed today
 * @param {Object} params.bcState.readinessState - NpcReadiness state map
 * @returns {Object} Debrief data for EndOfDayModal
 */
export function generateDebrief({
    todayLog = [],
    consequenceQueue = [],
    day = 1,
    stats = {},
    reputation = null,
    dailyQuestId = null,
    morningReputation = null,
    bcState = null,
}) {
    const summary = generateSummary(todayLog, stats, morningReputation, reputation);
    const criticalCases = extractCriticalCases(todayLog);
    const reflectionPrompts = generateReflectionPrompts(todayLog, criticalCases);
    const consequencePreview = getUpcomingFollowups(consequenceQueue, day, 7);

    // Build BC progress summary if bcState is provided
    const bcProgress = bcState ? buildBCProgress(bcState, day) : null;

    // V7 Fix #2: KARMA PENALTY — UKM neglect reduces overall score
    let finalScore = summary.overallScore;
    if (bcProgress && bcProgress.neglectWarnings.length > 0) {
        const penalty = bcProgress.neglectWarnings.length * 5;
        finalScore = Math.max(0, finalScore - penalty);
    }
    const grade = getGrade(finalScore);

    // Calculate XP bonus
    const baseXp = Math.round(finalScore * 0.5);
    const questBonus = resolvePriorityQuestBonus(day, dailyQuestId, summary);

    // V7 Fix #4: MAIA FORECAST — ominous whisper instead of spoiler details
    const incomingThreats = consequencePreview.filter(c => (c.returnDay - day) <= 2);
    const maiaForecast = incomingThreats.length > 0
        ? `[!] RADAR M.A.I.A: Terdeteksi anomali. ${incomingThreats.length} pasien berisiko komplikasi KRITIS dalam 48 jam. Bersiaplah.`
        : '[!] RADAR M.A.I.A: Cuaca klinis stabil. Tidak ada anomali terdeteksi.';

    return {
        day,
        summary,
        criticalCases,
        reflectionPrompts,
        maiaForecast,
        // Keep full consequencePreview for internal use but UI should prefer maiaForecast
        consequencePreview: consequencePreview.map(c => ({
            patientName: c.originalCase?.patientName || 'Pasien Follow-up',
            returnDay: c.returnDay,
            daysUntil: c.returnDay - day,
            condition: c.condition,
            severity: c.severity,
            narrative: c.narrative,
        })),
        grade,
        xpEarned: baseXp + questBonus,
        reflectionXpBonus: 20, // V7: bumped from 10 to incentivize reflection
        bcProgress,
        karmaPenalty: bcProgress?.neglectWarnings?.length > 0 ? bcProgress.neglectWarnings.length * 5 : 0,
    };
}

// ═══════════════════════════════════════════════════════════════
// SUB-GENERATORS
// ═══════════════════════════════════════════════════════════════

/**
 * Generate summary statistics from today's log.
 */
function generateSummary(todayLog, stats, morningReputation, reputation) {
    const patientsServed = todayLog.filter(c => c.completed || c.referred).length;
    const patientsMissed = todayLog.filter(c => c.missed || c.leftWithoutService).length;
    const referralsMade = todayLog.filter(c => c.referred).length;

    const diagnosisScores = todayLog
        .filter(c => c.diagnosisScore !== undefined && c.diagnosisScore !== null)
        .map(c => c.diagnosisScore);
    const avgDiagnosisScore = diagnosisScores.length > 0
        ? Math.round(diagnosisScores.reduce((a, b) => a + b, 0) / diagnosisScores.length)
        : 0;

    const correctDiagnoses = todayLog.filter(c => (c.diagnosisScore || 0) >= 80).length;
    const incorrectDiagnoses = todayLog.filter(c => c.completed && (c.diagnosisScore || 0) < 50).length;

    // V7 Fix #3: FINANCIAL TRIAGE — split umum revenue vs kapitasi burn
    const umumRevenue = todayLog.filter(c => (c.revenue || 0) > 0).reduce((sum, c) => sum + c.revenue, 0);
    const kapitasiBurned = todayLog.filter(c => (c.revenue || 0) < 0).reduce((sum, c) => sum + Math.abs(c.revenue), 0);
    const todayRevenue = umumRevenue - kapitasiBurned; // net
    const reputationValue = reputation ?? stats.reputation ?? 80;
    const reputationDelta = morningReputation !== null ? reputationValue - morningReputation : 0;

    // Calculate overall score (weighted average)
    const servingScore = patientsServed > 0 ? Math.min(100, (patientsServed / Math.max(1, patientsServed + patientsMissed)) * 100) : 50;
    const diagScore = avgDiagnosisScore || 50;
    const efficiencyScore = patientsMissed === 0 ? 100 : Math.max(0, 100 - patientsMissed * 20);

    const overallScore = Math.round(
        servingScore * 0.3 +
        diagScore * 0.5 +
        efficiencyScore * 0.2
    );

    return {
        patientsServed,
        patientsMissed,
        referralsMade,
        correctDiagnoses,
        incorrectDiagnoses,
        avgDiagnosisScore,
        todayRevenue,
        umumRevenue,
        kapitasiBurned,
        reputation: reputationValue,
        reputationDelta,
        overallScore,
    };
}

function resolvePriorityQuestBonus(day, dailyQuestId, summary) {
    if (!dailyQuestId) return 0;

    const priorityQuest = generatePriorityQuests({ day }).find((quest) => quest.id === dailyQuestId);
    if (!priorityQuest || typeof priorityQuest.check !== 'function') return 0;

    return priorityQuest.check(summary) ? Math.max(0, Number(priorityQuest.xpBonus) || 0) : 0;
}

/**
 * Extract the most critical/interesting cases for review.
 */
function extractCriticalCases(todayLog) {
    // Sort by impact: incorrect diagnoses first, then referrals, then good ones
    const scored = todayLog
        .filter(c => c.completed || c.referred)
        .map(c => ({
            ...c,
            impactScore:
                (c.diagnosisScore < 50 ? 100 : 0) +  // Wrong diagnosis = highest impact
                (c.referred ? 50 : 0) +                // Referral = interesting
                (c.diagnosisScore >= 90 ? 30 : 0) +    // Perfect diagnosis = noteworthy
                (c.complication ? 80 : 0),              // Complication = critical
        }))
        .sort((a, b) => b.impactScore - a.impactScore);

    return scored.slice(0, 3).map(c => {
        const generatedLearning = c.keyLearning ? null : generateKeyLearningMeta(c);

        return {
            patientName: c.patientName || 'Pasien',
            age: c.age,
            gender: c.gender,
            diagnosis: c.diagnosis || c.correctDiagnosis || 'Tidak terdiagnosis',
            correctDiagnosis: c.correctDiagnosis || c.diagnosis || null,
            diagnosisScore: c.diagnosisScore,
            wasCorrect: (c.diagnosisScore || 0) >= 70,
            referred: c.referred || false,
            vitals: c.vitals || {},
            guidelineRef: c.guidelineRef || null,
            treatmentGiven: c.treatmentGiven || [],
            // CaseLibrary pearls stay authoritative; generated fallbacks expose i18n metadata for UI.
            keyLearning: c.keyLearning || generatedLearning.text,
            keyLearningKey: generatedLearning?.key || null,
            keyLearningParams: generatedLearning?.params || {},
        };
    });
}

/**
 * Generate a key learning point for a case.
 */
function generateKeyLearning(caseRecord) {
    return generateKeyLearningMeta(caseRecord).text;
}

function generateKeyLearningMeta(caseRecord) {
    if ((caseRecord.diagnosisScore || 0) < 50) {
        const diagnosis = caseRecord.correctDiagnosis || caseRecord.diagnosis || '?';
        return {
            key: 'endOfDay.keyLearning.missedDiagnosis',
            params: { diagnosis },
            text: `Diagnosis yang tepat adalah "${diagnosis}". Perhatikan gejala-gejala kunci pada anamnesis.`
        };
    }
    if (caseRecord.referred) {
        return {
            key: 'endOfDay.keyLearning.referral',
            params: {},
            text: 'Kasus ini memerlukan rujukan. Pastikan stabilisasi sebelum pasien dikirim ke RS.'
        };
    }
    if ((caseRecord.diagnosisScore || 0) >= 90) {
        return {
            key: 'endOfDay.keyLearning.excellent',
            params: {},
            text: 'Diagnosa dan tatalaksana tepat. Pertahankan pola klinis seperti ini!'
        };
    }
    return {
        key: 'endOfDay.keyLearning.reviewFlow',
        params: {},
        text: 'Evaluasi kembali alur anamnesis dan pemeriksaan fisik untuk akurasi lebih tinggi.'
    };
}

/**
 * Generate reflection prompts based on today's cases.
 */
function generateReflectionPrompts(todayLog, criticalCases) {
    const prompts = [];

    // Prompt for missed diagnoses
    const missed = criticalCases.filter(c => !c.wasCorrect);
    if (missed.length > 0) {
        const missedCase = missed[0];
        const condition = missedCase.correctDiagnosis || 'kondisi pasien';
        prompts.push({
            type: 'missed_diagnosis',
            text: REFLECTION_TEMPLATES.missed_diagnosis(
                missedCase.patientName,
                condition
            ),
            patientName: missedCase.patientName,
            condition,
            category: 'critical',
        });
    }

    // Prompt for time management
    const totalMissed = todayLog.filter(c => c.missed).length;
    if (totalMissed > 2) {
        prompts.push({
            type: 'time_pressure',
            text: REFLECTION_TEMPLATES.time_pressure(),
            category: 'improvement',
        });
    }

    // Prompt for referrals
    const referredCases = criticalCases.filter(c => c.referred);
    if (referredCases.length > 0 && prompts.length < 3) {
        const referredCase = referredCases[0];
        prompts.push({
            type: 'referral_question',
            text: REFLECTION_TEMPLATES.referral_question(referredCase.patientName),
            patientName: referredCase.patientName,
            category: 'reflection',
        });
    }

    // Prompt for good cases
    const excellent = criticalCases.filter(c => c.wasCorrect && (c.diagnosisScore || 0) >= 90);
    if (excellent.length > 0 && prompts.length < 3) {
        const excellentCase = excellent[0];
        prompts.push({
            type: 'good_case',
            text: REFLECTION_TEMPLATES.good_case(excellentCase.patientName),
            patientName: excellentCase.patientName,
            category: 'positive',
        });
    }

    // Always include at least one prompt
    if (prompts.length === 0) {
        prompts.push({
            type: 'general',
            text: 'Apa satu hal yang akan kamu perbaiki besok di Puskesmas?',
            category: 'general',
        });
    }

    return prompts.slice(0, 3);
}

